<div class="page-title-wrap"><div><span class="eyebrow">ASSET MANAGEMENT</span><h1>Media Library</h1><p>Client and project assets stored in a secure, organized hierarchy.</p></div><button class="btn btn-primary" data-toggle="modal" data-target="#modal-add"><i class="fal fa-cloud-upload mr-1"></i> Upload media</button></div>
<section class="panel"><div class="panel-container show"><div class="panel-content"><div class="data-toolbar"><div class="input-group table-search"><div class="input-group-prepend"><span class="input-group-text bg-white"><i class="fal fa-search"></i></span></div><input class="form-control" data-table-search placeholder="Search files, clients, tags…"></div><span class="text-muted fs-sm"><?= count($rows) ?> stored assets</span></div>
<div class="table-responsive"><table class="table mb-0"><thead><tr><th>Asset</th><th>Client</th><th>Project</th><th>Type</th><th>Size</th><th>Captured</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $row): ?><tr data-table-row><td><div class="d-flex align-items-center"><div class="rounded bg-primary-50 text-primary p-2 mr-2"><i class="fal fa-<?= strpos($row['mime_type'],'image/')===0?'image':(strpos($row['mime_type'],'video/')===0?'video':'file') ?>"></i></div><div><strong class="d-block"><?= e($row['original_name']) ?></strong><small class="text-muted"><?= e($row['tags'] ?: 'No tags') ?></small></div></div></td><td><?= e($row['business_name']) ?></td><td><?= e($row['project_name'] ?: 'General') ?></td><td><?= e(ucwords(str_replace('_',' ',$row['content_type']))) ?></td><td><?= e(number_format($row['file_size']/1048576,2)) ?> MB</td><td><?= $row['captured_at']?e(date('M j, Y',strtotime($row['captured_at']))):'—' ?></td><td><span class="badge badge-soft-primary"><?= e($row['status']) ?></span></td><td class="text-right"><a class="btn btn-sm btn-outline-primary" href="<?= e(url('media_download',['id'=>$row['id']])) ?>"><i class="fal fa-download"></i></a></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="8"><div class="empty-state"><i class="fal fa-photo-video"></i><h3>No media uploaded</h3><p class="text-muted">Upload the first client asset to start the library.</p></div></td></tr><?php endif; ?></tbody></table></div></div></div></section>
<div class="modal fade" id="modal-add" tabindex="-1"><div class="modal-dialog modal-lg"><div class="modal-content"><form method="post" action="<?= e(url('media')) ?>" enctype="multipart/form-data"><div class="modal-header"><div><span class="eyebrow mb-1">SECURE UPLOAD</span><h2 class="modal-title fs-xl">Add media asset</h2></div><button class="close" type="button" data-dismiss="modal"><span>&times;</span></button></div><div class="modal-body"><input type="hidden" name="_token" value="<?= e(\AgencyOS\Csrf::token()) ?>"><input type="hidden" name="action" value="upload_media"><div class="row">
