<div class="col-md-6"><div class="form-group"><label>Project</label><select class="custom-select" name="project_id" id="media_project"><option value="">General client assets</option><?php foreach($options['projects'] as $project): ?><option value="<?= (int)$project['id'] ?>" data-client="<?= (int)$project['client_id'] ?>"><?= e($project['name']) ?></option><?php endforeach; ?></select></div></div>
