<div class="col-12"><div class="form-group"><label class="required">File</label><input class="form-control-file border rounded p-3 d-block w-100" type="file" name="media_file" accept="image/jpeg,image/png,image/webp,video/mp4,video/quicktime,application/pdf,.doc,.docx,.xls,.xlsx" required><small class="form-text text-muted">JPG, PNG, WebP, MP4, MOV, PDF, DOCX, or XLSX · maximum 25 MB.</small></div></div><div class="col-md-6"><div class="form-group"><label>Tags</label><input class="form-control" name="tags" placeholder="campaign, product, team"></div></div><div class="col-md-6"><div class="form-group"><label>Usage rights</label><input class="form-control" name="usage_rights" placeholder="Owned, licensed, expiry…"></div></div>
